4	// ── Agent Engine ────────────────────────────────────────────
5	// Simulates real-time agent collaboration with progressive message
6	// delivery, status changes, and progress updates.
7	
8	type Listener = () => void;
9	
10	interface EngineState {
11	  agentStatuses: Record<string, AgentStatus>;
12	  taskProgress: Record<string, number>;
13	  taskStatus: Record<string, TaskStatus>;
14	  visibleMessages: Record<string, AgentMessage[]>;
15	  activeTaskId: string | null;
16	}
17	
18	class AgentEngine {
19	  private state: EngineState;
20	  private listeners: Set<Listener> = new Set();
21	  private timers: ReturnType<typeof setTimeout>[] = [];
22	  private messageQueue: Map<string, AgentMessage[]> = new Map();
23	
24	  constructor() {
25	    // Initialize agent statuses
26	    const agentStatuses: Record<string, AgentStatus> = {};
27	    MOCK_AGENTS.forEach((a) => {
28	      agentStatuses[a.id] = a.status;
29	    });
30	
31	    this.state = {
32	      agentStatuses,
33	      taskProgress: {},
34	      taskStatus: {},
35	      visibleMessages: {},
36	      activeTaskId: null,
37	    };
38	  }
39	
40	  // ── Subscription ────────────────────────────────────
41	
42	  subscribe(listener: Listener) {
43	    this.listeners.add(listener);
44	    return () => this.listeners.delete(listener);
45	  }
46	
47	  private notify() {
48	    this.listeners.forEach((fn) => fn());
49	  }
50	
51	  getState() {
52	    return this.state;
53	  }
54	
55	  // ── Start watching a task (progressive message delivery) ──
56	
57	  watchTask(taskId: string) {
58	    if (this.state.activeTaskId === taskId) return;
59	
60	    this.cleanup();
61	    this.state.activeTaskId = taskId;
62	
63	    // Get all messages for this task
64	    const taskMessages = MOCK_AGENT_MESSAGES.filter(
65	      (m) => m.task_id === taskId
66	    );
67	
68	    if (!taskMessages.length) {
69	      this.state.visibleMessages[taskId] = [];
70	      this.notify();
71	      return;
72	    }
73	
74	    // Queue messages for progressive delivery
75	    this.messageQueue.set(taskId, [...taskMessages]);
76	    this.state.visibleMessages[taskId] = [];
77	
78	    // Set agents to working
79	    const agentIds = new Set(taskMessages.map((m) => m.agent_id));
80	    agentIds.forEach((id) => {
81	      this.state.agentStatuses[id] = "working";
82	    });
83	
84	    this.notify();
85	
86	    // Deliver messages one by one with realistic delays
87	    this.deliverNextMessage(taskId);
88	  }
89	
90	  private deliverNextMessage(taskId: string) {
91	    const queue = this.messageQueue.get(taskId);
92	    if (!queue || queue.length === 0) return;
93	
94	    const message = queue.shift()!;
95	
96	    // Determine delay based on message type
97	    let delay = 800;
98	    if (message.type === "thinking") delay = 600;
99	    if (message.type === "finding") delay = 1400;
100	    if (message.type === "suggestion") delay = 1800;
101	    if (message.type === "handoff") delay = 1000;
102	    if (message.type === "milestone") delay = 1200;
103	    if (message.type === "action") delay = 700;
104	
105	    const timer = setTimeout(() => {
106	      // Update agent status based on message type
107	      if (message.type === "thinking") {
108	        this.state.agentStatuses[message.agent_id] = "thinking";
109	      } else if (message.type === "finding" || message.type === "suggestion") {
110	        this.state.agentStatuses[message.agent_id] = "working";
111	      } else if (message.type === "milestone") {
112	        this.state.agentStatuses[message.agent_id] = "reviewing";
113	      }
114	
115	      // Add message to visible messages
116	      if (!this.state.visibleMessages[taskId]) {
117	        this.state.visibleMessages[taskId] = [];
118	      }
119	      this.state.visibleMessages[taskId] = [
120	        ...this.state.visibleMessages[taskId],
121	        message,
122	      ];
123	
124	      // Update progress
125	      const total = MOCK_AGENT_MESSAGES.filter(
126	        (m) => m.task_id === taskId
127	      ).length;
128	      const delivered = this.state.visibleMessages[taskId].length;
129	      this.state.taskProgress[taskId] = Math.round(
130	        (delivered / total) * 100
131	      );
132	
133	      this.notify();
134	
135	      // Continue delivering
136	      if (queue.length > 0) {
137	        this.deliverNextMessage(taskId);
138	      } else {
139	        // All messages delivered — set agents to completed
140	        const agentIds = new Set(
141	          MOCK_AGENT_MESSAGES.filter((m) => m.task_id === taskId).map(
142	            (m) => m.agent_id
143	          )
144	        );
145	        agentIds.forEach((id) => {
146	          this.state.agentStatuses[id] = "completed";
147	        });
148	        this.state.taskStatus[taskId] = "completed";
149	        this.notify();
150	      }
151	    }, delay);
152	
153	    this.timers.push(timer);
154	  }
155	
156	  // ── Load all messages instantly (for completed tasks) ─────
157	
158	  loadCompletedTask(taskId: string) {
159	    const taskMessages = MOCK_AGENT_MESSAGES.filter(
160	      (m) => m.task_id === taskId
161	    );
162	    this.state.visibleMessages[taskId] = taskMessages;
163	    this.state.taskProgress[taskId] = 100;
164	    this.state.taskStatus[taskId] = "completed";
165	    this.state.activeTaskId = taskId;
166	
167	    const agentIds = new Set(taskMessages.map((m) => m.agent_id));
168	    agentIds.forEach((id) => {
169	      this.state.agentStatuses[id] = "completed";
170	    });
171	
172	    this.notify();
173	  }
174	
175	  // ── Cleanup timers ────────────────────────────────────
176	
177	  cleanup() {
178	    this.timers.forEach(clearTimeout);
179	    this.timers = [];
180	    this.messageQueue.clear();
181	
182	    // Reset agents to idle
183	    MOCK_AGENTS.forEach((a) => {
184	      this.state.agentStatuses[a.id] = "idle";
185	    });
186	  }
187	
188	  // ── Get visible messages for a task ───────────────────
189	
190	  getMessages(taskId: string): AgentMessage[] {
191	    return this.state.visibleMessages[taskId] ?? [];
192	  }
193	
194	  // ── Get agent status ──────────────────────────────────
195	
196	  getAgentStatus(agentId: string): AgentStatus {
197	    return this.state.agentStatuses[agentId] ?? "idle";
198	  }
199	
200	  // ── Get task progress (0-100) ─────────────────────────
201	
202	  getTaskProgress(taskId: string): number {
203	    return this.state.taskProgress[taskId] ?? 0;
204	  }
205	}
206	
207	// Singleton engine instance
208	export const agentEngine = new AgentEngine();
